    test_single_tet_force_assembly_matches_shape_function_formula = _SoftBodyTests.test_single_tet_force_assembly_matches_shape_function_formula
    test_affine_multi_tet_patch_test_has_zero_interior_force = _SoftBodyTests.test_affine_multi_tet_patch_test_has_zero_interior_force
