    test_pressure_forces_match_current_area_vectors_and_per_face_pressures = _SoftBodyTests.test_pressure_forces_match_current_area_vectors_and_per_face_pressures
    test_pressure_forces_are_translation_invariant = _SoftBodyTests.test_pressure_forces_are_translation_invariant
    test_pressure_forces_rotate_covariantly_and_scalar_matches_per_face_values = _SoftBodyTests.test_pressure_forces_rotate_covariantly_and_scalar_matches_per_face_values
    test_uniform_pressure_on_closed_tetrahedron_has_zero_resultant = _SoftBodyTests.test_uniform_pressure_on_closed_tetrahedron_has_zero_resultant
    test_empty_pressure_face_set_has_zero_force = _SoftBodyTests.test_empty_pressure_face_set_has_zero_force
