    test_external_force_input_shape_is_validated = _SoftBodyTests.test_external_force_input_shape_is_validated
    test_jax_and_numpy_assembled_forces_agree_on_multi_tet_mesh = _SoftBodyTests.test_jax_and_numpy_assembled_forces_agree_on_multi_tet_mesh
    test_jax_and_numpy_force_paths_agree_for_both_materials = _SoftBodyTests.test_jax_and_numpy_force_paths_agree_for_both_materials
    test_jax_and_numpy_pressure_forces_agree_on_multiple_faces = _SoftBodyTests.test_jax_and_numpy_pressure_forces_agree_on_multiple_faces
    test_directional_force_matches_independent_finite_difference = _SoftBodyTests.test_directional_force_matches_independent_finite_difference
